// Тексты заголовков субтитров («שלב N מתוך 5», «המודעה נשלחה») автотест не читает — ручной взгляд (кейсы).
import { test, expect, Page, Locator } from '@playwright/test';
import { prepareReadOnly, GUIDES, openGuides, videoOf, startDesktop, expectPlaying, Guide } from './guides.helpers';

// #359741: /guides видит только админ (гость и user уходят на /) — сессия admin, файл сессии не перезаписывается.
test.use({ storageState: '../auth/admin.json', serviceWorkers: 'block' });

const SOURCE = { width: 720, height: 1558 };
const SYNC = 0.5; // с, норма context.md

type Frame = {
  plate: { top: number; bottom: number } | null; // px исходника
  step: number | null; // шаг формы publish по полосе прогресса (null — полосы в кадре нет)
  success: boolean; // экран «המודעה נשלחה בהצלחה»
  menuShade: number; // средняя яркость полосы справа (меню home открыто — < 80)
  diff: number | null; // разница с опорным кадром (если он сохранён)
};

async function seek(video: Locator, t: number) {
  await video.evaluate(
    (v: HTMLVideoElement, t: number) => new Promise((r) => { v.addEventListener('seeked', r, { once: true }); v.currentTime = t; }),
    t,
  );
}

/** Перемотать на t и разобрать кадр. saveRef — запомнить кадр как опорный для diff. */
async function frameAt(video: Locator, t: number, saveRef = false): Promise<Frame> {
  await seek(video, t);
  return video.evaluate((v: HTMLVideoElement, saveRef: boolean): Frame => {
    const W = v.videoWidth, H = v.videoHeight;
    const c = document.createElement('canvas'); c.width = W; c.height = H;
    const g = c.getContext('2d', { willReadFrequently: true })!;
    g.drawImage(v, 0, 0, W, H);
    const d = g.getImageData(0, 0, W, H).data;
    const at = (x: number, y: number) => (y * W + x) * 4;
    const orange = (i: number) => d[i] > 200 && d[i + 1] > 80 && d[i + 1] < 175 && d[i + 2] < 90;
    const gray = (i: number) => (d[i] + d[i + 1] + d[i + 2]) / 3;

    // Плашка субтитра: самая длинная серия строк с оранжевой полосой справа, ≥ 100 строк.
    const x0 = Math.round(W * 0.904), x1 = Math.round(W * 0.98);
    let best: { a: number; b: number } | null = null, cur: { a: number; b: number } | null = null;
    for (let y = 0; y < H; y++) {
      let n = 0;
      for (let x = x0; x < x1; x++) if (orange(at(x, y))) n++;
      if (n >= 3) {
        if (cur && y - cur.b <= 3) cur.b = y;
        else { if (cur && (!best || cur.b - cur.a > best.b - best.a)) best = cur; cur = { a: y, b: y }; }
      }
    }
    if (cur && (!best || cur.b - cur.a > best.b - best.a)) best = cur;
    if (best && best.b - best.a < 100) best = null;

    // Полоса прогресса формы publish: сплошная оранжевая строка, правый край x ≈ 640–656.
    let step: number | null = null;
    for (let y = 200; y < 450 && step === null; y++) {
      let n = 0, lo = W, hi = -1;
      for (let x = 0; x < W; x += 2) if (orange(at(x, y))) { n++; lo = Math.min(lo, x); hi = Math.max(hi, x); }
      if (n >= 40 && hi >= 640 && hi <= 656 && n * 2 >= (hi - lo) * 0.9) step = Math.round((hi - lo) / 116.4);
    }

    // Экран успеха: светло-зелёный круг + тёмно-зелёная галочка.
    let lg = 0, dg = 0;
    for (let y = 200; y < 460; y += 2) for (let x = 250; x < 470; x += 2) {
      const i = at(x, y), r = d[i], gg = d[i + 1], b = d[i + 2];
      if (gg > 200 && r < 235 && gg - r > 15 && gg - b > 10) lg++;
      if (gg > 120 && r < 90 && b < 130 && gg - r > 50) dg++;
    }

    // Затемнение справа (меню открыто).
    let s = 0, k = 0;
    for (let y = 300; y < 1400; y += 8) for (let x = 640; x < 716; x += 4) { s += gray(at(x, y)); k++; }

    // Разница с опорным кадром (y 100–1100, шаг 6).
    const sample: number[] = [];
    for (let y = 100; y < 1100; y += 6) for (let x = 0; x < W; x += 6) sample.push(gray(at(x, y)));
    const holder = v as HTMLVideoElement & { __qaRef?: number[] };
    let diff: number | null = null;
    if (saveRef) holder.__qaRef = sample;
    else if (holder.__qaRef) diff = sample.reduce((acc, val, i) => acc + Math.abs(val - holder.__qaRef![i]), 0) / sample.length;

    return {
      plate: best ? { top: best.a, bottom: best.b + 1 } : null,
      step,
      success: lg >= 2000 && dg >= 150,
      menuShade: s / k,
      diff,
    };
  }, saveRef);
}

/** /guides → видео запущено пользователем (фокус + «Пробел»), пауза; исходный кадр 720×1558. */
async function openPaused(page: Page, context: import('@playwright/test').BrowserContext, g: Guide) {
  await prepareReadOnly(context);
  await page.addLocatorHandler(page.getByRole('button', { name: 'אולי מאוחר יותר' }), (b) => b.click()); // попап установки на 375
  await openGuides(page);
  const video = videoOf(page, g);
  await startDesktop(page, video);
  await expectPlaying(video, 0.3, g.id);
  await video.evaluate((v: HTMLVideoElement) => v.pause());
  const size = await video.evaluate((v: HTMLVideoElement) => ({ w: v.videoWidth, h: v.videoHeight }));
  expect(size, `${g.id}: исходный кадр`).toEqual({ w: SOURCE.width, h: SOURCE.height });
  return video;
}

const guide = (id: Guide['id']) => GUIDES.find((x) => x.id === id)!;

// ─── GUIDES-17: publish, переходы 1→2…4→5 (замер принятой версии PR #199, etag 0203f8f1…, 2026-11-05) ───
// before — последний момент старой плашки (≥ 0,3 с до её ухода); gap — после ухода старой плашки, до экрана шага N;
// onNew — экран уже на шаге N, нового субтитра ещё нет (≥ 0,3 с до него); voice — начало фразы шага N (тишина аудио).
// barHidden — в момент «после голоса» полосы прогресса в кадре нет (субтитр наверху / запись прокручена): шаг не
// сверяется, проверяется только, что экран не на другом шаге.
const TRANSITIONS = [
  { n: 2, before: 49.0, gap: [49.6, 50.0], onNew: [50.4, 50.9, 51.4], voice: 51.63, barHidden: true }, // плашка (наверху) до 49,37 · экран 50,2 · плашка (наверху) 51,77
  { n: 3, before: 61.0, gap: [61.6, 61.9], onNew: [62.4, 63.0, 63.6], voice: 64.66, barHidden: true }, // 61,37 (наверху) · 62,17 · 64,73 (внизу; с 63,87 запись прокручена)
  { n: 4, before: 89.2, gap: [90.0, 90.6], onNew: [91.2, 91.4, 91.6], voice: 91.93, barHidden: false }, // 89,63 · 90,97 · 92,0
  { n: 5, before: 104.6, gap: [105.3, 105.6], onNew: [106.2, 106.6, 107.0], voice: 107.24, barHidden: false }, // 104,97 · 105,87 · 107,27
];

// ─── GUIDES-18: publish, конец (PR #199: плашка шага 5 до 1:59,57, экран успеха 2:00,80, голос 2:00,90, плашка «המודעה נשלחה» 2:00,97) ───
// successStart — первый кадр экрана успеха (замер кадров 30 fps); onSuccess — экран уже есть, плашки ещё нет (до неё 0,1 с).
const END = { before: 119.2, gap: [119.9, 120.4], successStart: 120.8, onSuccess: 120.87 };

// ─── GUIDES-19: home ~1:30–1:40 (меню 1:30,2–1:31,4, кабинет 1:31,6–1:31,8, голос описания 1:33,11) ───
const HOME = {
  ref: 89.6, // главная до меню (опорный кадр)
  scan: Array.from({ length: 17 }, (_, i) => Math.round((89.8 + i * 0.2) * 10) / 10), // 89,8 … 93,0
  menuOpenAfter: 89.8, // меню открывается не раньше
  menuClosedBy: 92.0, // и закрыто (после первого нажатия) не позже
  maxMenuOpen: 2.0, // с; принято 1,2 (повторное нажатие — ранее ~7 с)
  voice: 93.11, // начало описания «זה האזור האישי…»
  describe: [95, 97, 99], // описание идёт, меню закрыто
};

function suite(tag: '@desktop' | '@android', label: string) {
  for (const tr of TRANSITIONS) {
    test(`publish: переход ${tr.n - 1}→${tr.n} — субтитр прошлого шага не висит на экране шага ${tr.n}, новый — не позже ${SYNC} с от голоса, ${label} #13f060 #04a6d8 ${tag} @prod-safe`, async ({ page, context }) => {
      const video = await openPaused(page, context, guide('publish'));
      const at = (t: number) => `GUIDES-17 publish ${t} с (переход ${tr.n - 1}→${tr.n})`;

      const b = await frameAt(video, tr.before);
      expect(b.plate, `${at(tr.before)}: субтитр прошлого шага ещё на экране`).not.toBeNull();
      expect(b.step, `${at(tr.before)}: экран ещё не на шаге ${tr.n}`).not.toBe(tr.n);

      for (const t of tr.gap) {
        const f = await frameAt(video, t);
        expect(f.plate, `${at(t)}: субтитр прошлого шага убран до смены экрана`).toBeNull();
      }
      for (const t of tr.onNew) {
        const f = await frameAt(video, t);
        expect(f.step, `${at(t)}: экран на шаге ${tr.n} (полоса прогресса ${tr.n}/5)`).toBe(tr.n);
        expect(f.plate, `${at(t)}: на экране шага ${tr.n} нет плашки прошлого шага`).toBeNull();
      }
      const t = Math.round((tr.voice + SYNC - 0.05) * 100) / 100;
      const a = await frameAt(video, t);
      if (tr.barHidden) expect([tr.n, null], `${at(t)}: экран не на другом шаге (полоса прогресса закрыта субтитром наверху / запись прокручена)`).toContain(a.step);
      else expect(a.step, `${at(t)}: экран всё ещё шаг ${tr.n}`).toBe(tr.n);
      expect(a.plate, `${at(t)}: субтитр шага ${tr.n} появился не позже ${SYNC} с от начала фразы (голос ${tr.voice} с)`).not.toBeNull();
    });
  }

  test(`publish: конец — субтитр шага 5 не висит на экране успеха, «המודעה נשלחה» не позже ${SYNC} с от экрана, ${label} #13f060 #04a6d8 ${tag} @prod-safe`, async ({ page, context }) => {
    const video = await openPaused(page, context, guide('publish'));
    const at = (t: number) => `GUIDES-18 publish ${t} с`;

    const b = await frameAt(video, END.before);
    expect(b.plate, `${at(END.before)}: субтитр шага 5 перед «שלח»`).not.toBeNull();
    expect(b.success, `${at(END.before)}: экрана успеха ещё нет`).toBe(false);
    for (const t of END.gap) {
      const f = await frameAt(video, t);
      expect(f.success, `${at(t)}: экрана успеха ещё нет`).toBe(false);
      expect(f.plate, `${at(t)}: субтитр шага 5 убран до «שלח»`).toBeNull();
    }
    const s = await frameAt(video, END.onSuccess);
    expect(s.success, `${at(END.onSuccess)}: экран «המודעה נשלחה בהצלחה» (зелёный круг с галочкой)`).toBe(true);
    expect(s.plate, `${at(END.onSuccess)}: на экране успеха нет субтитра шага 5`).toBeNull();
    const t = Math.round((END.successStart + SYNC - 0.05) * 100) / 100;
    const a = await frameAt(video, t);
    expect(a.success, `${at(t)}: экран успеха`).toBe(true);
    expect(a.plate, `${at(t)}: субтитр «המודעה נשלחה» появился не позже ${SYNC} с от экрана успеха`).not.toBeNull();
  });

  test(`home ~1:31: «המודעות שלי» открывает кабинет с одного нажатия, описание кабинета — после экрана, ${label} #13f060 ${tag} @prod-safe`, async ({ page, context }) => {
    const video = await openPaused(page, context, guide('home'));
    const at = (t: number) => `GUIDES-19 home ${t} с`;

    const ref = await frameAt(video, HOME.ref, true);
    expect(ref.menuShade, `${at(HOME.ref)}: главная, меню закрыто`).toBeGreaterThanOrEqual(150);

    const open: number[] = [];
    const frames: { t: number; f: Frame }[] = [];
    for (const t of HOME.scan) {
      const f = await frameAt(video, t);
      frames.push({ t, f });
      if (f.menuShade < 80) open.push(t);
    }
    expect(open.length, `${at(HOME.scan[0])}–${HOME.scan.at(-1)} с: меню «תפריט» открыто (затемнение справа)`).toBeGreaterThan(0);
    const first = open[0], last = open.at(-1)!;
    const contiguous = frames.filter(({ t }) => t >= first && t <= last).every(({ f }) => f.menuShade < 80);
    expect(contiguous, `меню открыто одним отрезком ${first}–${last} с (не закрывалось и не открывалось повторно)`).toBe(true);
    expect(first, 'меню открывается после главной').toBeGreaterThanOrEqual(HOME.menuOpenAfter);
    expect(last, `меню закрыто после первого нажатия «המודעות שלי» — не позже ${HOME.menuClosedBy} с (ранее кабинет — только 1:37,4)`).toBeLessThan(HOME.menuClosedBy);
    expect(last - first, 'меню открыто недолго (одно нажатие)').toBeLessThanOrEqual(HOME.maxMenuOpen);

    // Сразу после меню — другой экран (אזור אישי), а не снова главная; описания ещё нет.
    for (const { t, f } of frames.filter(({ t }) => t >= last + 0.5)) {
      expect(f.menuShade, `${at(t)}: меню закрыто`).toBeGreaterThanOrEqual(80);
      expect(f.diff!, `${at(t)}: на экране не главная (разница с кадром ${HOME.ref} с)`).toBeGreaterThanOrEqual(30);
      if (t < HOME.voice - SYNC) expect(f.plate, `${at(t)}: описание кабинета не опережает экран`).toBeNull();
    }

    // Описание: субтитр не позже 0,5 с от голоса, меню закрыто, экран — кабинет.
    for (const t of [Math.round((HOME.voice + SYNC - 0.05) * 100) / 100, ...HOME.describe]) {
      const f = await frameAt(video, t);
      expect(f.plate, `${at(t)}: субтитр описания кабинета на экране (голос ${HOME.voice} с)`).not.toBeNull();
      expect(f.menuShade, `${at(t)}: описание идёт не над меню`).toBeGreaterThanOrEqual(80);
      expect(f.diff!, `${at(t)}: на экране кабинет, не главная`).toBeGreaterThanOrEqual(30);
    }
  });
}

test.describe('Видео-инструкции /guides — субтитры вместе с экраном (#13f060), десктоп 1440', () => {
  suite('@desktop', 'десктоп 1440');
});

test.describe('Видео-инструкции /guides — субтитры вместе с экраном (#13f060), мобильный 375', () => {
  test.use({ viewport: { width: 375, height: 812 } });
  suite('@android', 'мобильный 375');
});
